# Simplified envelope encryption. Real code uses libsodium / Tink, not raw RSA.
from os import urandom
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

def encrypt_photo(photo_bytes: bytes, viewer_public_keys: dict) -> dict:
    dek = urandom(32)  # 256-bit per-photo DEK, never reused
    nonce = urandom(12)
    ciphertext = AESGCM(dek).encrypt(nonce, photo_bytes, associated_data=None)
    # wrap() below is RSA-OAEP or ECIES seal with each viewer's public key
    envelopes = {uid: wrap(pub, dek) for uid, pub in viewer_public_keys.items()}
    return {"ct": ciphertext, "nonce": nonce, "envelopes": envelopes}

def decrypt_photo(bundle: dict, my_uid: str, my_private_key) -> bytes:
    wrapped = bundle["envelopes"][my_uid]
    dek = unwrap(my_private_key, wrapped)  # fails closed if revoked
    return AESGCM(dek).decrypt(bundle["nonce"], bundle["ct"], None)
